// ── SignerState wire ──────────────────────────────────────────────────────────

/**
 * Minimal ADR-0048 D6 signer-state projection consumed by [NostrLoginBlock].
 *
 * The full [org.nmp.android.model.SignerState] shape is the authoritative
 * version in the Chirp app; this is a gallery-local mirror to keep the
 * login-block self-contained (the gallery does not depend on the Chirp app
 * module). Both shapes must match the Rust `SignerStateDto` wire.
 */
@kotlinx.serialization.Serializable
data class LoginBlockSignerState(
    @kotlinx.serialization.SerialName("signer_kind") val signerKind: String = "",
    val state: String = "",
    val reason: String? = null,
    @kotlinx.serialization.SerialName("is_ready") val isReady: Boolean = false,
    @kotlinx.serialization.SerialName("is_awaiting_approval") val isAwaitingApproval: Boolean = false,
    @kotlinx.serialization.SerialName("is_reconnecting") val isReconnecting: Boolean = false,
    @kotlinx.serialization.SerialName("is_unavailable") val isUnavailable: Boolean = false,
    @kotlinx.serialization.SerialName("is_failed") val isFailed: Boolean = false,
)

// ── Presentation state (pure — unit-testable without Compose) ────────────────

/** Visual tone of a signer card. Derived ONLY from the pre-computed `is*`
 *  flags (ADR-0032 D6 — the shell never re-derives state from strings). */
enum class SignerCardTone { Default, InProgress, Ready, Degraded }

/**
 * Pure presentation state for one signer card. [SignerCard] renders exactly
 * this; the unit tests assert on exactly this — one source of truth for the
 * render rule, no test-side mirrors.
 */
data class SignerCardUi(
    val tone: SignerCardTone,
    /** Status line under the signer name; null = default "Sign in with …". */
    val statusLabel: String?,
    /** Replace the trailing chevron with a spinner. */
    val showSpinner: Boolean,
)

/** Map a signer-state projection value onto card presentation. */
internal fun signerCardUi(state: LoginBlockSignerState?): SignerCardUi {
    val isInProgress = state?.isAwaitingApproval == true || state?.isReconnecting == true
    val isDegraded = state?.isFailed == true || state?.isUnavailable == true
    val isReady = state?.isReady == true
    val tone = when {
        isDegraded -> SignerCardTone.Degraded
        isInProgress -> SignerCardTone.InProgress
        isReady -> SignerCardTone.Ready
        else -> SignerCardTone.Default
    }
    val statusLabel = when {
        state?.isUnavailable == true -> "Signer unavailable"
        state?.isFailed == true -> "Connection failed"
        state?.isAwaitingApproval == true -> "Waiting for approval…"
        state?.isReconnecting == true -> "Reconnecting…"
        isReady -> "Connected"
        else -> null
    }
    return SignerCardUi(tone = tone, statusLabel = statusLabel, showSpinner = isInProgress)
}

// ── NostrLoginBlock ───────────────────────────────────────────────────────────

/**
 * Login UI for Nostr apps using NMP.
 *
 * Detects installed local signer apps (currently Amber / `nostrsigner:` via
 * Android `PackageManager`) and surfaces each as a one-tap sign-in option.
 * Falls back to a manual key-entry path when no external signers are found —
 * matching the SwiftUI `NostrLoginBlock` at parity.
 *
 * ## NIP-55 flow
 *
 * When the user taps "Sign in with Amber":
 * 1. `onSignerSelected` fires with the chosen [NostrSignerInfo].
 * 2. The app should initiate the ADR-0048 `get_public_key` capability
 *    request via the [ExternalSignerCapabilityBridge].
 * 3. The `signerState` projection drives the `isAwaitingApproval` /
 *    `isReady` / `isUnavailable` / `isFailed` states shown inline.
 *
 * ## Testability (Stage 4)
 *
 * Every interactive element carries a `testTag` so the adb-driven
 * emulator E2E can locate and tap it without UI automation.
 *
 * ## Usage
 *
 * ```kotlin
 * NostrLoginBlock(
 *     onSignerSelected = { signer ->
 *         // call ExternalSignerCapabilityBridge to initiate get_public_key
 *     },
 *     onManualKey = {
 *         // navigate to your nsec / hex key entry view
 *     },
 * )
 * ```
 *
 * To show the in-progress / ready / error state while a sign-in is pending,
 * pass the current `signerState`:
 *
 * ```kotlin
 * NostrLoginBlock(
 *     onSignerSelected = { ... },
 *     onManualKey = { ... },
 *     signerState = model.signerState.collectAsStateWithLifecycle().value?.toLoginBlockState(),
 * )
 * ```
 *
 * @param onSignerSelected Called when the user taps a signer card. Provides
 *   the chosen [NostrSignerInfo]; the app initiates the capability flow.
 * @param onManualKey Called when the user taps "Enter your key".
 * @param signerState Optional live signer state driving the progress / health
 *   indicator. Null while no remote-signer session is in progress.
 * @param modifier Modifier applied to the root `Column`.
 */
@Composable
fun NostrLoginBlock(
    onSignerSelected: (NostrSignerInfo) -> Unit,
    onManualKey: () -> Unit,
    signerState: LoginBlockSignerState? = null,
    modifier: Modifier = Modifier,
) {
    val context = LocalContext.current
    var availableSigners by remember { mutableStateOf<List<NostrSignerInfo>>(emptyList()) }

    // Detection runs once on composition. Uses LaunchedEffect instead of
    // remember { detect() } so the PM probe happens asynchronously after
    // the first frame renders (mirrors the SwiftUI `.task { }` approach).
    LaunchedEffect(Unit) {
        availableSigners = detectInstalledSigners(context.packageManager)
    }

    Column(
        modifier = modifier.testTag("nostr_login_block"),
        verticalArrangement = Arrangement.spacedBy(12.dp),
    ) {
        // Signer cards — one per detected app.
        availableSigners.forEach { signer ->
            SignerCard(
                signer = signer,
                signerState = signerState?.takeIf { it.signerKind == "nip55" },
                onClick = { onSignerSelected(signer) },
            )
        }

        // Manual key entry — always present.
        ManualKeyButton(onClick = onManualKey)

        // Install hint — only shown when no signers are installed.
        if (availableSigners.isEmpty()) {
            InstallHint()
        }
    }
}

// ── Sub-composables ───────────────────────────────────────────────────────────

@Composable
private fun SignerCard(
    signer: NostrSignerInfo,
    signerState: LoginBlockSignerState?,
    onClick: () -> Unit,
) {
    // ONE render rule — the same pure function the unit tests assert on.
    val ui = signerCardUi(signerState)

    val borderColor: Color = when (ui.tone) {
        SignerCardTone.Degraded -> MaterialTheme.colorScheme.error
        SignerCardTone.InProgress -> Color(0xFFF59E0B) // amber-400
        SignerCardTone.Ready -> Color(0xFF22C55E) // green-500
        SignerCardTone.Default -> MaterialTheme.colorScheme.outline.copy(alpha = 0.5f)
    }

    OutlinedCard(
        modifier = Modifier
            .fillMaxWidth()
            .testTag("signer_card_${signer.displayName.lowercase()}")
            .semantics {
                contentDescription = "Sign in with ${signer.displayName}"
            }
            .clickable(onClick = onClick),
        shape = RoundedCornerShape(12.dp),
        border = BorderStroke(1.dp, borderColor),
        colors = CardDefaults.outlinedCardColors(
            containerColor = MaterialTheme.colorScheme.surfaceContainerLow,
        ),
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp, vertical = 14.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(14.dp),
        ) {
            // Leading icon
            Icon(
                imageVector = signerIcon(signer),
                contentDescription = null,
                modifier = Modifier.size(28.dp),
                tint = MaterialTheme.colorScheme.primary,
            )

            // Text column
            Column(
                modifier = Modifier.weight(1f),
                verticalArrangement = Arrangement.spacedBy(2.dp),
            ) {
                Text(
                    text = signer.displayName,
                    style = MaterialTheme.typography.bodyLarge.copy(
                        fontWeight = androidx.compose.ui.text.font.FontWeight.SemiBold,
                    ),
                )
                Text(
                    text = ui.statusLabel ?: "Sign in with ${signer.displayName}",
                    style = MaterialTheme.typography.bodySmall,
                    color = when (ui.tone) {
                        SignerCardTone.Degraded -> MaterialTheme.colorScheme.error
                        SignerCardTone.InProgress -> Color(0xFFF59E0B)
                        SignerCardTone.Ready -> Color(0xFF22C55E)
                        SignerCardTone.Default -> MaterialTheme.colorScheme.onSurfaceVariant
                    },
                )
            }

            // Trailing: spinner when pending, chevron otherwise.
            if (ui.showSpinner) {
                CircularProgressIndicator(
                    modifier = Modifier.size(18.dp),
                    color = Color(0xFFF59E0B),
                    strokeWidth = 2.dp,
                )
            } else {
                Icon(
                    imageVector = Icons.AutoMirrored.Filled.KeyboardArrowRight,
                    contentDescription = null,
                    modifier = Modifier.size(20.dp),
                    tint = MaterialTheme.colorScheme.onSurfaceVariant,
                )
            }
        }
    }
}

@Composable
private fun ManualKeyButton(onClick: () -> Unit) {
    OutlinedCard(
        modifier = Modifier
            .fillMaxWidth()
            .testTag("manual_key_button")
            .semantics { contentDescription = "Enter your private key manually" }
            .clickable(onClick = onClick),
        shape = RoundedCornerShape(12.dp),
        border = BorderStroke(
            1.dp,
            MaterialTheme.colorScheme.outline.copy(alpha = 0.5f),
        ),
        colors = CardDefaults.outlinedCardColors(
            containerColor = MaterialTheme.colorScheme.surfaceContainerLow,
        ),
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp, vertical = 14.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(14.dp),
        ) {
            Icon(
                imageVector = Icons.Default.Key,
                contentDescription = null,
                modifier = Modifier.size(28.dp),
                tint = MaterialTheme.colorScheme.onSurfaceVariant,
            )
            Column(
                modifier = Modifier.weight(1f),
                verticalArrangement = Arrangement.spacedBy(2.dp),
            ) {
                Text(
                    text = "Enter your key",
                    style = MaterialTheme.typography.bodyLarge.copy(
                        fontWeight = androidx.compose.ui.text.font.FontWeight.SemiBold,
                    ),
                )
                Text(
                    text = "Paste your nsec or hex private key",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
            }
            Icon(
                imageVector = Icons.AutoMirrored.Filled.KeyboardArrowRight,
                contentDescription = null,
                modifier = Modifier.size(20.dp),
                tint = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
    }
}

@Composable
private fun InstallHint() {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 4.dp),
        horizontalArrangement = Arrangement.Start,
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Text(
            text = "Install Amber or Primal for one-tap sign-in",
            style = MaterialTheme.typography.bodySmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
    }
}

// ── Icon helpers ──────────────────────────────────────────────────────────────

private fun signerIcon(signer: NostrSignerInfo): ImageVector = when (signer.intentScheme) {
    "nostrsigner" -> Icons.Default.Person // Amber
    "primal" -> Icons.Default.Key         // Primal (bolt icon not in default set)
    else -> Icons.Default.Key
}

package org.nmp.registry

import android.app.Activity
import android.content.Context
import android.content.Intent
import android.net.Uri
import androidx.activity.ComponentActivity
import androidx.activity.result.ActivityResultLauncher
import androidx.activity.result.contract.ActivityResultContracts
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json

// Wire types live in ExternalSignerWire.kt; the Amber-specific Intent/URI/
// permissions encoding and result extraction live in AmberIntentCodec.kt.
// The three files are vendored together as one unit (ADR-0048 Stage 2):
// byte-identical copies except the package line, see VendorDriftGateTest.

private val bridgeJson = Json {
    ignoreUnknownKeys = true
    isLenient = true
    classDiscriminator = "kind"
}

/**
 * D7 host adapter for the `external_signer` capability namespace.
 *
 * Receives fully-built `ExternalSignerRequest` objects from Rust, fires
 * the right OS IPC mechanism (Intent round-trip or ContentResolver
 * fast-path), and reports raw results back via `onResult` — it decides
 * nothing.
 *
 * ## Transport selection (D7 — mechanical, not policy)
 *
 * | Condition | Mechanism |
 * |---|---|
 * | `forceInteractive == true` | Intent |
 * | method is in `grantedPermissions` and `signerPackage` known | ContentResolver |
 * | otherwise | Intent |
 *
 * A ContentResolver returning `null` is reported as `Unavailable`; Rust
 * will re-issue the op with `force_interactive: true` to fall back to the
 * Intent path (D7 — the host never decides to retry).
 *
 * ## Lifecycle note
 *
 * The bridge registers an Activity Result launcher. Register it in
 * `Activity.onCreate` (before first `onStart`) via [register], not later.
 * Call [unregister] in `onDestroy` to release the launcher.
 *
 * @param activity The host activity (needed for `registerForActivityResult`).
 * @param onResult Called with the serialised `ExternalSignerResponse` JSON.
 *   Route this back to the kernel via `KernelBridge.deliverSignerResponse`.
 */
class ExternalSignerCapabilityBridge(
    private val activity: ComponentActivity,
    private val onResult: (responseJson: String) -> Unit,
) {

    // ── In-flight tracking ─────────────────────────────────────────────

    /** correlation_id of the request that is currently awaiting an Intent result. */
    @Volatile
    private var pendingCorrelationId: String? = null

    /** Method of the in-flight Intent (needed to build the response). */
    @Volatile
    private var pendingMethod: String? = null

    // ── Activity Result launcher ───────────────────────────────────────

    /**
     * Activity Result launcher registered for the `nostrsigner:` Intent.
     *
     * Android delivers the signer's reply as `Activity.RESULT_OK` with
     * extras (Amber `IntentUtils.sendResult`):
     * - `"result"` — the raw string value. For `sign_event` this is the
     *   SIGNATURE HEX ONLY; for `get_public_key` the pubkey; for
     *   encrypt/decrypt the ciphertext/plaintext.
     * - `"event"` — the full signed-event JSON (`sign_event` replies).
     *   Rust's `parse_signed_event_response` verifies id + schnorr sig on
     *   the complete event, so this extra — not `result` — is the value a
     *   `sign_event` reply must carry (Stage-4 emulator finding #3); see
     *   `selectAmberResultValue` in AmberIntentCodec.kt.
     * - `"package"` — the signer app's package name (present on
     *   `get_public_key` replies; Amber-specific).
     * - `"rejected"` — boolean; Amber returns `RESULT_OK` with this flag
     *   (instead of `RESULT_CANCELED`) when the user rejects with a
     *   remember-choice. Reported as `Rejected`.
     *
     * `RESULT_CANCELED` means the user navigated back without approving —
     * reported as `Rejected`.
     */
    private var launcher: ActivityResultLauncher<Intent>? = null

    /**
     * Register the Activity Result launcher. Call from `Activity.onCreate`
     * BEFORE first `onStart`. Safe to call multiple times; subsequent calls
     * are no-ops.
     */
    fun register() {
        if (launcher != null) return
        launcher = activity.registerForActivityResult(
            ActivityResultContracts.StartActivityForResult(),
        ) { result ->
            val correlationId = pendingCorrelationId ?: return@registerForActivityResult
            pendingCorrelationId = null
            val method = pendingMethod ?: "unknown"
            pendingMethod = null

            val response = if (result.resultCode == Activity.RESULT_OK) {
                val data = result.data
                val rawResult = selectAmberResultValue(
                    method = method,
                    eventExtra = data?.getStringExtra("event"),
                    resultExtra = data?.getStringExtra("result"),
                )
                val signerPackage = data?.getStringExtra("package")
                if (data?.getBooleanExtra("rejected", false) == true) {
                    // Amber reports remembered rejections as RESULT_OK +
                    // `rejected: true` (not RESULT_CANCELED).
                    ExternalSignerResponse(
                        correlationId = correlationId,
                        outcome = ExternalSignerOutcome.Rejected(
                            reason = "signer rejected the request",
                        ),
                    )
                } else if (rawResult != null) {
                    ExternalSignerResponse(
                        correlationId = correlationId,
                        outcome = ExternalSignerOutcome.Ok(result = rawResult),
                        signerPackage = signerPackage.takeIf {
                            method == "get_public_key" && it != null
                        },
                    )
                } else {
                    ExternalSignerResponse(
                        correlationId = correlationId,
                        outcome = ExternalSignerOutcome.Unavailable(
                            reason = "signer returned no result",
                        ),
                    )
                }
            } else {
                ExternalSignerResponse(
                    correlationId = correlationId,
                    outcome = ExternalSignerOutcome.Rejected(
                        reason = "user cancelled",
                    ),
                )
            }
            onResult(bridgeJson.encodeToString(response))
        }
    }

    /**
     * Unregister the launcher. Call from `Activity.onDestroy`.
     * Safe to call when not registered.
     */
    fun unregister() {
        launcher?.unregister()
        launcher = null
    }

    // ── Dispatch ───────────────────────────────────────────────────────

    /**
     * Handle an `ExternalSignerRequest` built by Rust.
     *
     * Selects the transport path mechanically from `forceInteractive` +
     * `grantedPermissions`, then dispatches. D7: no policy decisions here.
     *
     * For the gallery showcase this is called with a stateless callback
     * wired to `onResult`. For Chirp it is wired into the kernel via
     * `nativeDeliverSignerResponse` (see `KernelBridge`).
     */
    fun handle(request: ExternalSignerRequest) {
        if (shouldUseContentResolver(request)) {
            dispatchContentResolver(request)
        } else {
            dispatchIntent(request)
        }
    }

    /**
     * Parse a raw `ExternalSignerRequest` JSON string and dispatch.
     * Called from the capability callback registered with the kernel.
     *
     * D6: malformed JSON is silently dropped (no crash); it degrades to
     * timeout on the Rust side (the correlation_id sender is never resolved).
     */
    fun handleJson(requestJson: String) {
        val request = try {
            bridgeJson.decodeFromString<ExternalSignerRequest>(requestJson)
        } catch (_: Exception) {
            return // D6: malformed — degrade to timeout
        }
        handle(request)
    }

    // ── Intent path ───────────────────────────────────────────────────

    private fun dispatchIntent(request: ExternalSignerRequest) {
        val intent = buildAmberSignerIntent(request)

        val existing = pendingCorrelationId
        if (existing != null) {
            reportUnavailable(
                request.correlationId,
                "external signer Intent already pending for correlation $existing",
            )
            return
        }

        pendingCorrelationId = request.correlationId
        pendingMethod = request.method

        val l = launcher
        if (l != null) {
            l.launch(intent)
        } else {
            // Launcher not registered — report Unavailable so Rust can toast.
            pendingCorrelationId = null
            pendingMethod = null
            reportUnavailable(request.correlationId, "capability bridge not registered")
        }
    }

    // ── ContentResolver fast-path ─────────────────────────────────────

    private fun dispatchContentResolver(request: ExternalSignerRequest) {
        val pkg = request.signerPackage ?: run {
            reportUnavailable(request.correlationId, "signer package unknown for ContentResolver path")
            return
        }
        val method = request.method.toNostrSignerMethod()
        val authority = "$pkg.$method"
        val uri = Uri.parse("content://$authority")

        // NIP-55 ContentResolver call: the selection string carries the payload
        // and optional counterparty and current_user fields.
        val selectionArgs = arrayOf(
            request.payload,
            request.counterparty ?: "",
            request.currentUser ?: "",
        )

        try {
            val cursor = activity.contentResolver.query(
                uri,
                null,  // projection
                null,  // selection (Amber uses selectionArgs directly)
                selectionArgs,
                null,  // sortOrder
            )

            cursor?.use { c ->
                if (c.moveToFirst()) {
                    val resultCol = c.getColumnIndex("result")
                    val rawResult = if (resultCol >= 0) c.getString(resultCol) else null
                    if (rawResult != null) {
                        val resp = ExternalSignerResponse(
                            correlationId = request.correlationId,
                            outcome = ExternalSignerOutcome.Ok(result = rawResult),
                        )
                        onResult(bridgeJson.encodeToString(resp))
                    } else {
                        // null result = silently-revoked permission. Report Unavailable;
                        // Rust re-issues with force_interactive = true.
                        reportUnavailable(request.correlationId, "ContentResolver returned null result")
                    }
                } else {
                    reportUnavailable(request.correlationId, "ContentResolver returned empty cursor")
                }
            } ?: reportUnavailable(request.correlationId, "ContentResolver returned null cursor")
        } catch (e: Exception) {
            reportUnavailable(request.correlationId, "ContentResolver error: ${e.message}")
        }
    }

    // ── Helpers ───────────────────────────────────────────────────────

    private fun reportUnavailable(correlationId: String, reason: String) {
        val resp = ExternalSignerResponse(
            correlationId = correlationId,
            outcome = ExternalSignerOutcome.Unavailable(reason = reason),
        )
        onResult(bridgeJson.encodeToString(resp))
    }

    companion object {
        /**
         * Detect installed Nostr signer apps using the PackageManager.
         * Convenience wrapper over [detectInstalledSigners].
         */
        fun detect(context: Context): List<NostrSignerInfo> =
            detectInstalledSigners(context.packageManager)
    }
}

package org.nmp.registry

import android.content.Intent
import android.content.pm.PackageManager
import android.net.Uri
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

// ── Wire types mirroring nmp-signer-iface ExternalSignerRequest/Response ──────
//
// Vendored with ExternalSignerCapabilityBridge.kt + AmberIntentCodec.kt as one
// unit (ADR-0048 Stage 2): byte-identical copies except the package line, see
// VendorDriftGateTest.

/**
 * Mirror of `ExternalSignerRequest` from `nmp-signer-iface`.
 *
 * Rust builds this and serialises it as `CapabilityRequest.payload_json`.
 * The Kotlin host fires it and reports the raw result — it decides nothing (D7).
 */
@Serializable
data class ExternalSignerRequest(
    @SerialName("correlation_id") val correlationId: String,
    val method: String,
    val payload: String,
    @SerialName("current_user") val currentUser: String? = null,
    val counterparty: String? = null,
    val permissions: List<Nip55Permission> = emptyList(),
    @SerialName("granted_permissions") val grantedPermissions: List<Nip55Permission> = emptyList(),
    @SerialName("signer_package") val signerPackage: String? = null,
    @SerialName("force_interactive") val forceInteractive: Boolean = false,
)

/** Mirror of `Nip55Permission` from `nmp-signer-iface`. */
@Serializable
data class Nip55Permission(val kind: String)

/**
 * Mirror of `ExternalSignerResponse` from `nmp-signer-iface`.
 *
 * The host fills this and hands it back to Rust via `deliverResponse`.
 * D7: raw results only, no interpretation.
 */
@Serializable
data class ExternalSignerResponse(
    @SerialName("correlation_id") val correlationId: String,
    val outcome: ExternalSignerOutcome,
